import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.api.distmarker.OnlyIn;

@OnlyIn(value=Dist.CLIENT)
public class ClientQuestData {
    private static final Set<String> completedIds = new HashSet<String>();
    private static final Set<String> completedAdvancements = new HashSet<String>();

    public static void updateCompleted(Set<String> ids) {
        completedIds.clear();
        completedIds.addAll(ids);
    }

    public static void updateAdvancements(Set<String> ids) {
        completedAdvancements.clear();
        completedAdvancements.addAll(ids);
    }

    public static boolean hasCompleted(String id) {
        return completedIds.contains(id);
    }

    public static boolean hasAdvancement(String id) {
        return completedAdvancements.contains(id);
    }

    public static Set<String> getCompletedIds() {
        return Collections.unmodifiableSet(completedIds);
    }
}

