public class DamageIndicatorManager {
    public static final int LIFETIME_TICKS = 50;
    private static final int MAX_ENTRIES = 40;
    private static final List<DamageIndicatorEntry> ENTRIES = new ArrayList<DamageIndicatorEntry>();
    private static final Random RANDOM = new Random();

    public static void add(float rawDamage, float elemDamage, DamageTypes.ElementType elemType, float rawHz, Vec3 worldPos) {
        if (!((Boolean)ModConfig.CLIENT.SHOW_DAMAGE_INDICATORS.get()).booleanValue()) {
            return;
        }
        if (ENTRIES.size() >= 40) {
            ENTRIES.remove(0);
        }
        float driftX = (RANDOM.nextFloat() - 0.5f) * 0.6f;
        ENTRIES.add(new DamageIndicatorEntry(rawDamage, elemDamage, elemType, rawHz, worldPos, driftX));
    }

    public static void tick() {
        Iterator<DamageIndicatorEntry> iter = ENTRIES.iterator();
        while (iter.hasNext()) {
            DamageIndicatorEntry e = iter.next();
            ++e.age;
            if (e.age < 50) continue;
            iter.remove();
        }
    }

    public static List<DamageIndicatorEntry> getEntries() {
        return ENTRIES;
    }

    public static class DamageIndicatorEntry {
        public final int rawDamage;
        public final int elemDamage;
        public final DamageTypes.ElementType elemType;
        public final float rawHz;
        public final Vec3 worldPos;
        public final float driftX;

